CREATE TABLE track_events (  id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '自增主键',  event_id VARCHAR(64) NOT NULL COMMENT '事件ID e01~e12',  event_name VARCHAR(128) NOT NULL COMMENT '事件英文名称',  user_id VARCHAR(128) NOT NULL COMMENT '用户ID',  culture_id VARCHAR(64) COMMENT '非遗/特产品类ID，关联素材',  event_time DATETIME NOT NULL COMMENT '事件发生时间',  is_demo TINYINT DEFAULT 0 COMMENT '是否DEMO数据：1=DEMO，0=真实数据',  ext_info JSON COMMENT '扩展字段，存放额外参数',  INDEX idx_userid (user_id),  INDEX idx_eventtime (event_time),  INDEX idx_eventid (event_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户行为埋点表';